<script setup>
import { onMounted,ref } from 'vue'
import { api,send,money } from '../api'
const orders=ref([]),loading=ref(true),error=ref(''),busy=ref(null),message=ref(''),demo=ref(false)
const labels={PENDING:'待付款',PAID:'待发货',SHIPPED:'已发货',CANCELLED:'已取消'}
async function load(){try{[orders.value,{demo:demo.value}]=await Promise.all([api('/orders'),api('/config')])}catch(e){error.value=e.message}finally{loading.value=false}}
async function action(order,type){busy.value=order.id;error.value='';message.value='';try{await api(`/orders/${order.id}/${type}`,send('POST'));message.value=type==='pay'?'模拟付款成功，等待发货':'订单已取消，库存已回补';await load()}catch(e){error.value=e.message}finally{busy.value=null}}
onMounted(load)
</script>
<template><section class="page"><div class="page-title"><div><p class="subtle">FOLLOW YOUR FINDS</p><h1>我的订单</h1></div><RouterLink to="/">发现更多好物 ↗</RouterLink></div><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="loading" class="empty">正在读取订单…</p><div v-else-if="!orders.length" class="empty"><h2>你的第一份好物，即将启程。</h2><RouterLink to="/" class="button">去逛逛</RouterLink></div><article v-for="o in orders" :key="o.id" class="order"><div class="order-heading"><div><h3>HC-{{String(o.id).padStart(6,'0')}}</h3><p class="muted">{{new Date(o.created_at).toLocaleString('zh-CN')}} · {{o.country}} · {{o.currency}}</p></div><span class="badge" :class="o.status">{{labels[o.status]}}</span></div><div class="order-lines"><div v-for="item in o.items" :key="item.id"><span>{{item.name}} <span class="muted">× {{item.quantity}}</span></span><strong>{{money(item.unit_price*item.quantity,o.currency)}}</strong></div></div><div class="order-bottom"><div><p>{{o.recipient}} · {{o.address}}</p><p v-if="o.tracking">物流单号：<strong>{{o.tracking}}</strong></p><p class="muted">运费 {{money(o.shipping,o.currency)}} · 合计 <strong>{{money(o.total,o.currency)}}</strong></p></div><div v-if="o.status==='PENDING'" class="actions"><button class="button secondary" :disabled="busy===o.id" @click="action(o,'cancel')">取消订单</button><button v-if="demo" class="button" :disabled="busy===o.id" @click="action(o,'pay')">模拟付款</button></div></div></article></section></template>
